package managed

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"google.golang.org/protobuf/proto"
	pb "kingdom/internal/execution/openshell/managedpb"
	"os"
	"testing"
)

// This fixture is generated by the Rust backend test, not the Go encoder.
func TestRustCanonicalVectors(t *testing.T) {
	type vector struct {
		Canonical string `json:"canonical_hex"`
		SHA       string `json:"sha256"`
		Wire      string `json:"wire_hex"`
	}
	var fixture struct {
		Command vector   `json:"command_spec"`
		Start   vector   `json:"start_execution_request"`
		Receipt vector   `json:"terminal_receipt"`
		Chunks  []vector `json:"output_chunks"`
		Frames  vector   `json:"output_frames"`
	}
	raw, e := os.ReadFile("../../../../contracts/openshell-managed/canonical-vectors.json")
	if e != nil {
		t.Fatal(e)
	}
	if e = json.Unmarshal(raw, &fixture); e != nil {
		t.Fatal(e)
	}
	for name, item := range map[string]struct {
		v vector
		m proto.Message
	}{"command": {fixture.Command, &pb.CommandSpec{}}, "start": {fixture.Start, &pb.StartExecutionRequest{}}, "receipt": {fixture.Receipt, &pb.TerminalReceipt{}}} {
		t.Run(name, func(t *testing.T) {
			v := item.v
			b, e := hex.DecodeString(v.Canonical)
			if e != nil || len(b) == 0 {
				t.Fatal("missing vector", e)
			}
			if e = proto.Unmarshal(b, item.m); e != nil {
				t.Fatal(e)
			}
			encoded, e := Canonical(item.m)
			if e != nil || !bytes.Equal(encoded, b) {
				t.Fatal("Rust/Go encoding mismatch", e)
			}
			d, e := Digest(item.m)
			if e != nil || hex.EncodeToString(d) != v.SHA {
				t.Fatal("Rust/Go digest mismatch", e)
			}
			if v.Wire != "" {
				wire, _ := hex.DecodeString(v.Wire)
				var receipt pb.TerminalReceipt
				if e = proto.Unmarshal(wire, &receipt); e != nil {
					t.Fatal(e)
				}
				if ValidateReceipt(&receipt, receipt.Identity) != nil {
					t.Fatal("Rust receipt rejected")
				}
			}
		})
	}
	verifier := NewOutputVerifier()
	for _, v := range fixture.Chunks {
		b, _ := hex.DecodeString(v.Canonical)
		var c pb.OutputChunk
		if e = proto.Unmarshal(b, &c); e != nil {
			t.Fatal(e)
		}
		if e = verifier.Add(&c); e != nil {
			t.Fatal(e)
		}
	}
	if hex.EncodeToString(verifier.h.Sum(nil)) != fixture.Frames.SHA {
		t.Fatal("Rust/Go framed output mismatch")
	}
}
